@startuml

class Agency {
  + Search(key: string) : void
}

class Property {
  + code: string
  + address: string
  + zipCode: string
  + city: string
  + area: int
  + GetTypeAndProperties() : string
  + Contains(key: string) : boolean
  + PrintCard() : void
}

class Garage extends Property {
  + parkingSpaces: int
}

class Apartment extends Property {
  + numberOfRooms: int
  + numberOfBathrooms: int
}

class Villa extends Apartment {
  + gardenArea: int
}

Agency "1" -- "*" Property

@enduml

